def ability
  return GameData::Ability.try_get(@ability_id)
end

def ability=(value)
  new_ability = GameData::Ability.try_get(value)
  @ability_id = (new_ability) ? new_ability.id : nil
end

def pbUpdate(fullChange = false)
  return if !@pokemon
  @pokemon.calc_stats
  @level          = @pokemon.level
  @hp             = @pokemon.hp
  @totalhp        = @pokemon.totalhp
  if !@effects[PBEffects::Transform]
    @attack       = @pokemon.attack
    @defense      = @pokemon.defense
    @spatk        = @pokemon.spatk
    @spdef        = @pokemon.spdef
    @speed        = @pokemon.speed
    if fullChange
      @types      = @pokemon.types
      @ability_id = @pokemon.ability_id
    end
  end
end

def pbTransform(target)
  oldAbil = @ability_id
  @effects[PBEffects::Transform]        = true
  @effects[PBEffects::TransformSpecies] = target.species
  pbChangeTypes(target)
  self.ability = target.ability
  @attack  = target.attack
  @defense = target.defense
  @spatk   = target.spatk
  @spdef   = target.spdef
  @speed   = target.speed
  GameData::Stat.each_battle { |s| @stages[s.id] = target.stages[s.id] }
  if Settings::NEW_CRITICAL_HIT_RATE_MECHANICS
    @effects[PBEffects::FocusEnergy] = target.effects[PBEffects::FocusEnergy]
    @effects[PBEffects::LaserFocus]  = target.effects[PBEffects::LaserFocus]
  end
  @moves.clear
  target.moves.each_with_index do |m, i|
    @moves[i] = Battle::Move.from_pokemon_move(@battle, Pokemon::Move.new(m.id))
    @moves[i].pp       = 5
    @moves[i].total_pp = 5
  end
  @effects[PBEffects::Disable]      = 0
  @effects[PBEffects::DisableMove]  = nil
  @effects[PBEffects::WeightChange] = target.effects[PBEffects::WeightChange]
  @battle.scene.pbRefreshOne(@index)
  @battle.pbDisplay(_INTL("{1} transformed into {2}!", pbThis, target.pbThis(true)))
  pbOnLosingAbility(oldAbil)
end

def pbChangeTypes(newType)
  if newType.is_a?(Battle::Battler)
    newTypes = newType.pbTypes
    newTypes.push(:NORMAL) if newTypes.length == 0
    newExtraType = newType.effects[PBEffects::ExtraType]
    newExtraType = nil if newTypes.include?(newExtraType)
    @types = newTypes.clone
    @effects[PBEffects::ExtraType] = newExtraType
  else
    newType = GameData::Type.get(newType).id
    @types = [newType]
    @effects[PBEffects::ExtraType] = nil
  end
  @effects[PBEffects::BurnUp] = false
  @effects[PBEffects::Roost]  = false
end

def pbEORCountDownFieldEffect(effect, msg)
  return if @field.effects[effect] <= 0
  @field.effects[effect] -= 1
  return if @field.effects[effect] > 0
  pbDisplay(msg)
  if effect == PBEffects::MagicRoom
    pbPriority(true).each { |battler| battler.pbItemTerrainStatBoostCheck }
  end
end

def pbOnLosingAbility(oldAbil, suppressed = false)
  if oldAbil == :NEUTRALIZINGGAS && (suppressed || !@effects[PBEffects::GastroAcid])
    pbAbilitiesOnNeutralizingGasEnding
  elsif [:UNNERVE, :ASONECHILLINGNEIGH, :ASONEGRIMNEIGH].include?(oldAbil) &&
        (suppressed || !@effects[PBEffects::GastroAcid])
    pbItemsOnUnnerveEnding
  elsif oldAbil == :ILLUSION && @effects[PBEffects::Illusion]
    @effects[PBEffects::Illusion] = nil
    if !@effects[PBEffects::Transform]
      @battle.scene.pbChangePokemon(self, @pokemon)
      @battle.pbDisplay(_INTL("{1}'s {2} wore off!", pbThis, GameData::Ability.get(oldAbil).name))
      @battle.pbSetSeen(self)
    end
  end
  @effects[PBEffects::GastroAcid] = false if unstoppableAbility?
  @effects[PBEffects::SlowStart]  = 0 if self.ability != :SLOWSTART
  @effects[PBEffects::Truant]     = false if self.ability != :TRUANT
  # Check for end of primordial weather
  @battle.pbEndPrimordialWeather
  # Revert form if Flower Gift/Forecast was lost
  pbCheckFormOnWeatherChange(true)
  # Abilities that trigger when the terrain changes
  pbAbilityOnTerrainChange(true)
end

def self.triggerOnTerrainChange(ability, battler, battle, ability_changed)
  OnTerrainChange.trigger(ability, battler, battle, ability_changed)
end

def pbRefreshOne(idxBattler)
  @sprites["dataBox_#{idxBattler}"]&.refresh
end

def pbShowAnimation(id, user, targets, hitNum = 0, showAnimation = true)
  return if !showAnimation
  if user.effects[PBEffects::ParentalBond] == 1
    @battle.pbCommonAnimation("ParentalBond", user, targets)
  else
    @battle.pbAnimation(id, user, targets, hitNum)
  end
end

class Battle::Move::StartSwapAllBattlersBaseDefensiveStats < Battle::Move
  def pbEffectGeneral(user)
    if @battle.field.effects[PBEffects::WonderRoom] > 0
      @battle.field.effects[PBEffects::WonderRoom] = 0
      @battle.pbDisplay(_INTL("Wonder Room wore off, and the Defense and Sp. Def stats returned to normal!"))
    else
      @battle.field.effects[PBEffects::WonderRoom] = 5
      @battle.pbDisplay(_INTL("It created a bizarre area in which the Defense and Sp. Def stats are swapped!"))
    end
  end

  def pbShowAnimation(id, user, targets, hitNum = 0, showAnimation = true)
    return if @battle.field.effects[PBEffects::WonderRoom] > 0   # No animation
    super
  end
end

class HandlerHashSymbol
  def initialize
    @hash    = {}
    @add_ifs = {}
  end

  def [](sym)
    sym = sym.id if !sym.is_a?(Symbol) && sym.respond_to?("id")
    return @hash[sym] if sym && @hash[sym]
    @add_ifs.each_value do |add_if|
      return add_if[1] if add_if[0].call(sym)
    end
    return nil
  end

  def add(sym, handler = nil, &handlerBlock)
    if ![Proc, Hash].include?(handler.class) && !block_given?
      raise ArgumentError, "#{self.class.name} for #{sym.inspect} has no valid handler (#{handler.inspect} was given)"
    end
    @hash[sym] = handler || handlerBlock if sym
  end

  def addIf(sym, conditionProc, handler = nil, &handlerBlock)
    if ![Proc, Hash].include?(handler.class) && !block_given?
      raise ArgumentError, "addIf call for #{sym} in #{self.class.name} has no valid handler (#{handler.inspect} was given)"
    end
    @add_ifs[sym] = [conditionProc, handler || handlerBlock]
  end

  def copy(src, *dests)
    handler = self[src]
    return if !handler
    dests.each { |dest| add(dest, handler) }
  end

  def remove(key)
    @hash.delete(key)
  end

  def clear
    @hash.clear
    @add_ifs.clear
  end

  def trigger(sym, *args)
    sym = sym.id if !sym.is_a?(Symbol) && sym.respond_to?("id")
    handler = self[sym]
    return handler&.call(sym, *args)
  end
end

class Battle::ActiveField
  attr_accessor :effects
  attr_accessor :defaultWeather
  attr_accessor :weather
  attr_accessor :weatherDuration
  attr_accessor :defaultTerrain
  attr_accessor :terrain
  attr_accessor :terrainDuration

  def initialize
    @effects = []
    @effects[PBEffects::AmuletCoin]      = false
    @effects[PBEffects::FairyLock]       = 0
    @effects[PBEffects::FusionBolt]      = false
    @effects[PBEffects::FusionFlare]     = false
    @effects[PBEffects::Gravity]         = 0
    @effects[PBEffects::HappyHour]       = false
    @effects[PBEffects::IonDeluge]       = false
    @effects[PBEffects::MagicRoom]       = 0
    @effects[PBEffects::MudSportField]   = 0
    @effects[PBEffects::PayDay]          = 0
    @effects[PBEffects::TrickRoom]       = 0
    @effects[PBEffects::WaterSportField] = 0
    @effects[PBEffects::WonderRoom]      = 0
    @defaultWeather  = :None
    @weather         = :None
    @weatherDuration = 0
    @defaultTerrain  = :None
    @terrain         = :None
    @terrainDuration = 0
  end
end
